from pathlib import Path

from syft_migration import ReleasedPackageProtocolInfo, ReleasedProtocol

from .registry import job_registry

# Release artifacts of past syft-job releases:
#   syft-job-<package_version>.json  (ReleasedPackageProtocolInfo, every release)
#   protocol-<protocol_version>.json (ReleasedProtocol, only when the protocol changed)
# Generated by export_release_artifact.py; 0.1.38 / protocol 0 predate the
# artifact mechanism, so their files are hardcoded as if that release had
# emitted them.
HISTORY_DIR = Path(__file__).parent / "history"


def register_historic_schemas() -> None:
    """Register the release artifacts of past releases into the job registry.

    Must run after the versioned models are imported: with
    ``raise_for_unknown_objects`` an artifact listing an object version this
    release cannot load fails at import time instead of at migration time.
    """
    for path in sorted(HISTORY_DIR.glob("syft-job-*.json")):
        job_registry.register_released_package_protocol_info(
            ReleasedPackageProtocolInfo.load(path), raise_for_unknown_objects=True
        )
    for path in sorted(HISTORY_DIR.glob("protocol-*.json")):
        job_registry.register_released_protocol(
            ReleasedProtocol.load(path), raise_for_unknown_objects=True
        )
